    public function run(): void
    {
        $now = now();

        foreach (array_chunk(self::FOODS, 50) as $foods) {
            $rows = array_map(fn (array $food) => [
                'name' => $food[0],
                'ingredients' => $food[1],
                'calories' => $food[2],
                'protein' => $food[3],
                'carbohydrates' => $food[4],
                'fat' => $food[5],
                'serving_size' => $food[6],
                'serving_unit' => $food[7],
                'created_at' => $now,
                'updated_at' => $now,
            ], $foods);

            DB::table('food')->upsert(
                $rows,
                ['name'],
                ['ingredients', 'calories', 'protein', 'carbohydrates', 'fat', 'serving_size', 'serving_unit', 'updated_at']
            );
        }
    }
